'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,cents} from '@/lib/pilot';
import {billingDollars} from './billing-accounts';
import {invoiceAddressFields,invoiceArgs,invoiceReceipt,invoiceRequest,invoiceReview,invoiceStatus,type InvoiceRequest,type InvoiceReview,type InvoiceScope} from '@/lib/billing-invoice-create';
type Props=InvoiceScope&{onSaved:(number:string)=>void;onBusyChange?:(busy:boolean)=>void};
export function CreateBillingInvoice(props:Props){return <InvoiceForm key={[props.actor,props.tenant,props.property,props.account].join('/')} {...props}/>}
function InvoiceForm(props:Props){
 const key=['irp-issue-invoice',props.actor,props.tenant,props.property,props.account].join('/');
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key);return {pending:raw?invoiceRequest(JSON.parse(raw),props):null,error:''}}catch{return {pending:null,error:'Saved invoice request could not be read. Restore browser storage before continuing.'}}});
 const [pending,setPending]=useState<InvoiceRequest|null>(initial.pending),[draft,setDraft]=useState<InvoiceRequest|null>(null),[review,setReview]=useState<InvoiceReview|null>(null);
 const [selected,setSelected]=useState<Record<string,string>>({}),[bill,setBill]=useState(''),[issuer,setIssuer]=useState(''),[due,setDue]=useState(''),[cancelReason,setCancelReason]=useState('');
 const [billAddress,setBillAddress]=useState<Record<string,string>>({}),[issuerAddress,setIssuerAddress]=useState<Record<string,string>>({});
 const address=(value:Record<string,string>)=>Object.fromEntries(invoiceAddressFields.map(([key])=>[key,key==='country_code'?(value[key]??'').trim().toUpperCase():(value[key]??'').trim()]).filter(([,value])=>value));
 const [busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[done,setDone]=useState(false);
 const lock=useRef(false),alive=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 useEffect(()=>{props.onBusyChange?.(busy);return()=>props.onBusyChange?.(false)},[busy,props.onBusyChange]);
 async function run(action:()=>Promise<void>){if(lock.current||initial.error)return;lock.current=true;setBusy(true);setError('');try{await action()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Invoice action could not be completed.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function load(){setReview(null);setDraft(null);setSelected({});const result=invoiceReview(await hotelRpc('billing_invoice_review',{p_tenant:props.tenant,p_property:props.property,p_account:props.account}),props);if(alive.current){setReview(result);setDue(result.business_date);setDone(false);setNotice('')}}
 function prepare(){try{if(!review)throw Error('Load available charges first.');if(due<review.business_date)throw Error('Due date cannot be before the issue date.');const lines=review.lines.filter(l=>Object.hasOwn(selected,l.route_id)).map(l=>{const amount=String(cents(selected[l.route_id]));if(BigInt(amount)>BigInt(l.available_minor))throw Error('An amount exceeds the available charge.');return {route_id:l.route_id,amount_minor:amount}});const total=lines.reduce((sum,l)=>sum+BigInt(l.amount_minor),0n).toString();setDraft(invoiceRequest({version:1,actor:props.actor,tenant:props.tenant,property:props.property,account:props.account,request:crypto.randomUUID(),due,bill:{legal_name:bill.trim(),...address(billAddress)},issuer:{legal_name:issuer.trim(),...address(issuerAddress)},lines,hash:review.review_hash,total},props));setError('')}catch(e){setError(e instanceof Error?e.message:'Review invoice details.')}}
 async function save(checkOnly=false){const r=pending??draft;if(!r||done||(!checkOnly&&r.cancellation))return;invoiceRequest(r,props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  let number:string|null;try{number=checkOnly?invoiceStatus(await hotelRpc('billing_invoice_status',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request}),r):invoiceReceipt(await hotelRpc('issue_billing_invoice',invoiceArgs(r)),r)}catch{throw Error('Invoice could not be confirmed. Check the saved result or retry the same request.');}
  if(!alive.current)return;if(!number){setNotice('No issued invoice found. Retry this request, or cancel it before preparing a replacement.');return}
  sessionStorage.removeItem(key);setPending(null);setDraft(null);setDone(true);setNotice(`Invoice ${number} issued. No payment was collected.`);props.onSaved(number);
 }
 async function cancel(){if(!pending)return;const reason=pending.cancellation??cancelReason.trim();if(reason.length<4||reason.length>500)throw Error('Enter a cancellation reason of 4–500 characters.');const r={...pending,cancellation:reason};invoiceRequest(r,props);sessionStorage.setItem(key,JSON.stringify(r));setPending(r);
  const result=await hotelRpc<Record<string,unknown>>('retire_billing_invoice',{p_tenant:r.tenant,p_property:r.property,p_account:r.account,p_request:r.request,p_reason:reason,p_confirmed:true});
  if(result.tenant_id!==r.tenant||result.property_id!==r.property||result.account_id!==r.account||result.request_id!==r.request||result.actor_id!==r.actor||result.reason!==reason||result.retired!==true||result.money_moved!==false)throw Error('Cancellation could not be verified. Retry the saved cancellation.');
  if(!alive.current)return;sessionStorage.removeItem(key);setPending(null);setDraft(null);setReview(null);setNotice('Unsaved invoice request cancelled. Load charges to prepare another invoice.');
 }
 const current=pending??draft;
 return <section className="pilot-settings" aria-label="Create company invoice"><h3>Create invoice</h3><p>Select transferred charges and verify the legal names before issuing. This does not collect payment or email the invoice.</p>
 {error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}
 <fieldset disabled={busy||!!initial.error} style={{border:0,padding:0,margin:0}}>
 {!pending&&!draft&&!done&&<><button className="secondary" onClick={()=>void run(load)}>Load invoice charges</button>{review&&<><p>{review.account_name} · Available {billingDollars(review.available_minor)}</p>{!review.lines.length&&<p>No transferred charges are available to invoice.</p>}
 {review.lines.map(line=><div key={line.route_id}><label><input type="checkbox" checked={Object.hasOwn(selected,line.route_id)} onChange={e=>{const checked=e.target.checked;setSelected(previous=>{const next={...previous};if(checked)next[line.route_id]=(Number(line.available_minor)/100).toFixed(2);else delete next[line.route_id];return next})}}/> {line.source_booking_id} · {line.source_key} · Available {billingDollars(line.available_minor)}</label>{Object.hasOwn(selected,line.route_id)&&<label className="field">Amount for {line.source_booking_id} / {line.source_key}<input inputMode="decimal" value={selected[line.route_id]} onChange={e=>setSelected({...selected,[line.route_id]:e.target.value})}/></label>}</div>)}
 <label className="field">Bill to legal name<input maxLength={200} value={bill} onChange={e=>setBill(e.target.value)}/></label><label className="field">Issuing hotel legal name<input maxLength={200} value={issuer} onChange={e=>setIssuer(e.target.value)}/></label><details><summary>Billing and hotel addresses / tax IDs</summary>{invoiceAddressFields.map(([key,label,max])=><div key={key}><label className="field">Bill to {label}<input maxLength={max} value={billAddress[key]??''} onChange={e=>setBillAddress({...billAddress,[key]:e.target.value})}/></label><label className="field">Hotel {label}<input maxLength={max} value={issuerAddress[key]??''} onChange={e=>setIssuerAddress({...issuerAddress,[key]:e.target.value})}/></label></div>)}</details><label className="field">Invoice due date<input type="date" min={review.business_date} value={due} onChange={e=>setDue(e.target.value)}/></label><button className="primary" disabled={!Object.keys(selected).length} onClick={prepare}>Review invoice</button></>}</>}
 {current&&!done&&<><p>Bill to: {current.bill.legal_name}</p><p>{invoiceAddressFields.map(([key])=>current.bill[key]).filter(Boolean).join(', ')}</p><p>Issued by: {current.issuer.legal_name}</p><p>{invoiceAddressFields.map(([key])=>current.issuer[key]).filter(Boolean).join(', ')}</p><p>{current.lines.length} charges · Total {billingDollars(current.total)} · Due {current.due}</p><button className="primary" disabled={!!current.cancellation} onClick={()=>void run(()=>save())}>{pending?'Retry saved invoice':'Confirm and issue invoice'}</button>{!pending&&<button className="secondary" onClick={()=>setDraft(null)}>Edit invoice details</button>}
 {pending&&<><button className="secondary" onClick={()=>void run(()=>save(true))}>Check invoice result</button><label className="field">Cancel unsaved invoice reason<textarea maxLength={500} disabled={!!pending.cancellation} value={pending.cancellation??cancelReason} onChange={e=>setCancelReason(e.target.value)}/></label><p>Cancel only an unsaved request. An issued invoice requires a credit note.</p><button className="secondary" onClick={()=>void run(cancel)}>{pending.cancellation?'Retry saved invoice cancellation':'Cancel unsaved invoice request'}</button></>}</>}
 </fieldset>{busy&&<p role="status">Working on invoice…</p>}</section>;
}
